"""Generate the shared browser registry from the reviewed constellation definitions."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
rows=json.loads((ROOT/'resources/constellations.json').read_text())
encoded=json.dumps(rows,ensure_ascii=False,separators=(',',':'))
source='''/* Generated by scripts/generate_constellations.py; edit resources/constellations.json. */
(function(root){
 const definitions=__DATA__;
 const byId=new Map(definitions.map(row=>[row.id,row])),identities=new Map(),scopes=new Map();
 for(const row of definitions)for(const id of row.ids){if(!row.parent)identities.set(id,row.id);if(!scopes.has(id))scopes.set(id,[]);scopes.get(id).push(row.id);}
 function numbered(row,name){const range=row.numbered;if(!range||!name.startsWith(range.prefix))return false;const rest=name.slice(range.prefix.length),match=rest.match(/^(\\d+)(?![\\w])/);if(!match)return false;const n=Number(match[1]);return n>=range.min&&n<=range.max;}
 function family(s){
  const id=s.id??s.NORAD_CAT_ID,name=s.name||s.OBJECT_NAME||'';
  if(s.family&&byId.has(s.family))return s.family;
  if(s.object_type==='DEB'||s.object_type==='R/B')return 'debris';
  if(identities.has(id))return identities.get(id);
  const debris=byId.get('debris');if(debris&&(debris.prefixes.some(p=>name.startsWith(p))||debris.contains.some(p=>name.includes(p))))return 'debris';
  if(id===25544)return 'iss';
  if(name.startsWith('STARLINK'))return 'starlink';
  if(/^(?:GPS (?:B|III)|NAVSTAR \\d)/.test(name))return 'gps';
  if(/^(?:GSAT\\d{4}(?:\\s|\\(|$)|GIOVE-[AB]|GALILEO(?:[ -]|$))/.test(name))return 'galileo';
  return definitions.find(row=>!row.parent&&(numbered(row,name)||row.prefixes.some(p=>name.startsWith(p))||row.contains.some(p=>name.includes(p))))?.id||null;
 }
 function memberships(s){if(s.collections)return s.collections;const primary=family(s);if(!primary)return [];const other=scopes.get(s.id??s.NORAD_CAT_ID)||[];return other.includes(primary)?other:[primary,...other.filter(key=>byId.get(key).parent)];}
 function belongs(s,collection){return memberships(s).includes(collection);}
 // One physical marker; a chosen subgroup colour takes precedence over a white parent.
 function displayFamily(s,colors,enabled){const choices=memberships(s).filter(key=>!enabled||enabled.has(key));return choices.find(key=>colors&&colors[key]&&colors[key]!=='#ffffff'&&byId.get(key).parent)||choices.find(key=>colors&&colors[key]&&colors[key]!=='#ffffff')||choices.find(key=>key===family(s))||choices[0]||family(s);}
 const api={definitions,byId,family,memberships,belongs,displayFamily};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.AtlasCollections=api;
})(globalThis);
'''.replace('__DATA__',encoded)
(ROOT/'static/constellations.js').write_text(source)
# Keep the menu and Atlas cards aligned with the same reviewed registry.
import html
page=ROOT/'static/index.html';text=page.read_text()
a=text.index('<option value="all">');b=text.index('</select>',a)
text=text[:a]+'<option value="all">Tous les satellites</option>'+''.join('<option value="'+r['id']+'"'+(' selected' if r['id']=='starlink' else '')+'>'+html.escape(r['label'])+'</option>' for r in rows)+text[b:]
a=text.index('<div class="atlas-family-list">');b=text.index('<p class="hint">',a)
def card(row):
    key=row['id'];label=html.escape(row['label'])
    return '<div class="atlas-family-card"><div class="atlas-family-main"><label><input type="checkbox" data-family="'+key+'" checked><span><strong>'+label+'</strong><small id="atlas-count-'+key+'">—</small></span></label><a class="atlas-page-link" data-page="'+key+'" href="/'+key+'">Voir la page</a></div><div class="atlas-color-control"><input type="color" id="atlas-color-'+key+'" value="#ffffff" aria-label="Couleur : '+label+'" title="Choisir la couleur"><label for="atlas-color-'+key+'">Modifier la couleur</label></div></div>'
categories=[('stations','Stations spatiales'),('navigation','Satellites de navigation'),('telecommunications','Télécommunications'),('observation','Observation de la Terre'),('weather','Météo et climat'),('science','Sciences et astronomie')]
debris_card='<section class="atlas-debris-card" aria-label="Débris spatiaux"><div class="atlas-family-card"><div class="atlas-family-main"><label><input type="checkbox" data-family="debris" hidden><span><strong>Débris spatiaux</strong><small id="atlas-count-debris">—</small></span></label><p class="atlas-debris-note">Masqués par défaut pour garder une vue lisible.</p><button id="atlas-debris-toggle" type="button" aria-pressed="false">Afficher les débris</button><a class="atlas-page-link" data-page="debris" href="/debris">Voir la page</a></div><div class="atlas-color-control"><input type="color" id="atlas-color-debris" value="#ffffff" aria-label="Couleur : Débris spatiaux" title="Choisir la couleur"><label for="atlas-color-debris">Modifier la couleur</label></div></div></section>'
groups=[debris_card]
for key,label in categories:
    members=[r for r in rows if r['category']==key]
    groups.append('<details class="atlas-category" data-category="'+key+'"><summary>'+html.escape(label)+'<span class="atlas-category-total">'+str(len(members))+'</span></summary><div class="atlas-category-actions"><button type="button" data-theme-select="all">Tout sélectionner</button><button type="button" data-theme-select="none">Tout désélectionner</button><label class="atlas-theme-color"><input type="color" data-theme-color="'+key+'" value="#ffffff" aria-label="Couleur du thème : '+html.escape(label)+'">Même couleur</label></div><div class="atlas-category-items">'+''.join(card(row) for row in members)+'</div></details>')
text=text[:a]+'<div class="atlas-family-list">'+''.join(groups)+'</div>'+text[b:]
page.write_text(text)
